namespace Northfield.Fiscal.Desktop.Resources;

internal static class CompanyActionIcons
{
    private static Image Decode(string value)
    {
        using var stream = new MemoryStream(Convert.FromBase64String(value));
        using var image = Image.FromStream(stream);
        return new Bitmap(image);
    }

    public static Image Novo() => Decode(NovoPng);
    public static Image Editar() => Decode(EditarPng);
    public static Image Excluir() => Decode(ExcluirPng);
    public static Image Selecionar() => Decode(SelecionarPng);
    public static Image Duplicar() => Decode(DuplicarPng);
    public static Image AtivarInativar() => Decode(AtivarInativarPng);
    public static Image Historico() => Decode(HistoricoPng);
    public static Image Certificado() => Decode(CertificadoPng);
    public static Image Importar() => Decode(ImportarPng);
    public static Image Exportar() => Decode(ExportarPng);

    private const string NovoPng = "";
    private const string EditarPng = "";
    private const string ExcluirPng = "";
    private const string SelecionarPng = "";
    private const string DuplicarPng = "";
    private const string AtivarInativarPng = "";
    private const string HistoricoPng = "";
    private const string CertificadoPng = "";
    private const string ImportarPng = "";
    private const string ExportarPng = "";
}